head.script:
scwin.onpageload = function() {
    windowContainer1.createWindow({
        "title": "Source",
        "src": "windowContainer_existWindowd_WESD-670_(WSQ-4724)_subFrm.xml",
        "windowTitle": "frmaeTest",
        "openAction": "existWindow",
        "windowId": "M003",
        "frameMode": "wframe" // "frameMode" 옵션을 "wframe"으로 적용.
    });
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    debugger;
    windowContainer1.createWindow({
        "title": "Source",
        "src": "windowContainer_existWindowd_WESD-670_(WSQ-4724)_subFrm.xml",
        "windowTitle": "frmaeTest",
        "openAction": "existWindow",
        "windowId": "M003",
        "frameMode": "wframe" // "frameMode" 옵션을 "wframe"으로 적용.
    });
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'windowContainer1_subWindow0_wframe_testPop').style.zIndex == ''", "true");
    WebSquare.wUnit.addCommand("pause", "300");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
